12	
13	/** Local-time first/last day of the current month grid (6 weeks), so the
14	 *  initial fetch matches the Month view the client opens on. */
15	function initialRange(): [string, string] {
16	  const now = new Date();
17	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
18	  const gridStart = new Date(firstOfMonth);
19	  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
20	  const gridEnd = new Date(gridStart);
21	  gridEnd.setDate(gridEnd.getDate() + 42);
22	  return [gridStart.toISOString(), gridEnd.toISOString()];
23	}
24	
25	export default async function CalendarPage() {
26	  await requireUser();
27	
28	  let calendars: CalendarInfo[] = [];
29	  let events: CalEvent[] = [];
30	  let tasks: TaskItem[] = [];
31	  let failed = false;
32	
33	  try {
34	    calendars = await listCalendars();
35	    if (calendars.length > 0) {
36	      const [start, end] = initialRange();
37	      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
38	    }
39	  } catch {
40	    failed = true;
41	  }
42	
43	  // An outage and an empty account are OPPOSITE situations and must not share a
44	  // screen: telling a paying mailbox owner whose CalDAV server hiccuped that they
45	  // have "no calendar connected" — and pushing them to buy email they already own
46	  // — hides the fault and sends them the wrong way. mail/page.tsx already splits
47	  // these; this page used to fold both into the empty state.
48	  if (failed) {
49	    return (
50	      <div className="mx-auto max-w-2xl pt-10">
51	        <EmptyState
52	          title="Couldn't reach your calendar"
53	          sub="We couldn't load your calendar just now — this is usually a brief hiccup on the calendar server, not a problem with your account. Reload in a moment; if it keeps happening, open a support ticket and we'll look into it."
54	          action={
55	            <Link href="/dashboard/calendar" className="btn-primary">
56	              Reload
57	            </Link>
58	          }
59	        />
60	      </div>
61	    );
62	  }
63	
64	  if (calendars.length === 0) {
65	    return (
66	      <div className="mx-auto max-w-2xl pt-10">
67	        <EmptyState
68	          title="No calendar connected"
69	          sub="Your calendar lives alongside your Nxeon mailbox. Set up business email on one of your domains to start scheduling events and tracking tasks here."
70	          action={
71	            <Link href="/dashboard/email" className="btn-primary">
72	              Set up email
73	            </Link>
74	          }
75	        />
76	      </div>
77	    );
78	  }
79	
80	  return (
81	    <>
82	      <PortalHero variant="calendar" title="Calendar" sub="Your schedule, events, and tasks." />
83	      <CalendarClient initialCalendars={calendars} initialEvents={events} initialTasks={tasks} />
84	    </>
85	  );
86	}
