1	import { redirect } from "next/navigation";
2	import { LoginForm } from "@/components/AuthForms";
3	import { AuthShell } from "@/components/marketing/AuthShell";
4	import { currentUser } from "@/lib/auth";
5	import { safeNext } from "@/lib/safe-next";
6	import { googleOauthConfigured } from "@/lib/google-oauth";
7	import { roleHome } from "@/lib/portal-home";
8	
9	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
10	const GOOGLE_ERRORS: Record<string, string> = {
11	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
12	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
13	  google_cancelled: "Google sign-in was cancelled.",
14	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
15	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
16	  google_error: "Couldn't finish signing in with Google. Please try again.",
17	  account_suspended: "This account is suspended.",
18	};
19	
20	export default async function LoginPage({
21	  searchParams,
22	}: {
23	  searchParams: Promise<{ next?: string; error?: string }>;
24	}) {
25	  // Where the visitor was heading before the login wall. Public CTAs pass this so
26	  // signing in lands them on what they actually clicked instead of a generic
27	  // dashboard. Validated by `safeNext` — an unchecked `next` on a login form is an
28	  // open redirect and therefore a phishing primitive — so it is never trusted,
29	  // here or in the action.
30	  const { next, error } = await searchParams;
31	  const dest = safeNext(next ?? null);
32	  // Only ever surface a message from our own fixed map — never echo the raw
33	  // query value into the page.
34	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
35	
36	  // Already signed in? Then this page is just a waypoint: send them where they
37	  // were going. Without this, a public CTA written as `/login?next=/dashboard/x`
38	  // would strand EXISTING customers on a sign-in form they do not need — trading
39	  // one dead end for a worse one, since it asks a paying customer to authenticate
40	  // twice.
41	  const user = await currentUser();
42	  if (user) redirect(dest ?? roleHome(user.role));
43	
44	  return (
45	    <AuthShell
46	      heading="Welcome back"
47	      sub="Sign in to manage your servers and billing."
48	      bullets={[
49	        "Instant NVMe VPS provisioning",
50	        "Real-time metrics and one-click reinstalls",
51	        "Full root access on every plan",
52	      ]}
53	    >
54	      {/* The VALIDATED destination, never the raw query value: a rejected
55	          `next` must not be echoed into the DOM at all. It could not cause a
56	          redirect (the action re-validates), but rendering attacker-supplied
57	          text into a form for no reason is how the next bug starts. */}
58	      <LoginForm next={dest ?? undefined} googleEnabled={googleOauthConfigured()} googleError={googleError} />
59	    </AuthShell>
60	  );
61	}
