235	function CreateTokenForm() {
236	  const [state, action, pending] = useActionState(createApiToken, {});
237	  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
238	  // `<form action={fn}>` submit, so a rejected token blanked the name and the
239	  // expiry — and, worse, silently reset the SCOPE checkboxes to their defaults.
240	  // A customer who ticked `write`, hit a validation error and pressed Create
241	  // again would have created a read-only token while believing they had asked
242	  // for write. A control that quietly changes a permission choice is the one
243	  // field on this form that must never lose what it was given.
244	  const [name, setName] = useState("");
245	  const [expiresDays, setExpiresDays] = useState("");
246	  const [scopes, setScopes] = useState<{ read: boolean; write: boolean }>({ read: true, write: false });
247	  const wasPending = useRef(false);
248	  useEffect(() => {
249	    if (wasPending.current && !pending && state?.token) {
250	      setName("");
251	      setExpiresDays("");
252	      setScopes({ read: true, write: false });
253	    }
254	    wasPending.current = pending;
255	  }, [pending, state]);
256	  return (
257	    <div className="space-y-4">
258	      {state?.token && (
259	        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/[0.06] p-4">
260	          <p className="mb-2 text-sm font-medium text-emerald-300">
261	            Token created — copy it now, it won&apos;t be shown again.
262	          </p>
263	          <code className="block break-all rounded-lg border border-white/10 bg-black/30 px-3 py-2 font-mono text-sm">
264	            {state.token}
265	          </code>
266	        </div>
267	      )}
268	      <form action={action} className="space-y-4">
269	        {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
270	        <div className="grid gap-4 sm:grid-cols-3">
271	          <div className="sm:col-span-1">
272	            <label className="label" htmlFor="api-token-name">
273	              Token name
274	            </label>
275	            <input
276	              id="api-token-name"
277	              className="input"
278	              name="name"
279	              required
280	              maxLength={60}
281	              placeholder="ci-deploy"
282	              value={name}
283	              onChange={(e) => setName(e.target.value)}
284	            />
285	          </div>
286	          <div>
287	            <label className="label" htmlFor="api-token-expiry">
288	              Expires (days)
289	            </label>
290	            <input
291	              id="api-token-expiry"
292	              className="input"
293	              name="expiresDays"
294	              type="number"
295	              min={1}
296	              placeholder="never"
297	              value={expiresDays}
298	              onChange={(e) => setExpiresDays(e.target.value)}
299	            />
300	          </div>
301	          {/* `write` is offered but the public API is currently READ-ONLY — the only
302	              token-authenticated endpoint is GET /api/v1/servers. Granting write
303	              therefore permits nothing today, and a customer ticking it to automate
304	              changes would find it silently useless. Say so on the control rather
305	              than accepting a choice that does nothing. */}
306	          <div>
307	            <label className="label">Scopes</label>
308	            <div className="flex items-center gap-4 pt-2 text-sm">
309	              <label className="flex items-center gap-1.5">
310	                <input
311	                  type="checkbox"
312	                  name="scopes"
313	                  value="read"
314	                  checked={scopes.read}
315	                  onChange={(e) => setScopes((s) => ({ ...s, read: e.target.checked }))}
316	                />{" "}
317	                read
318	              </label>
319	              <label
320	                className="flex items-center gap-1.5 text-slate-500"
321	                title="The public API is read-only for now, so this grants nothing yet."
322	              >
323	                <input
324	                  type="checkbox"
325	                  name="scopes"
326	                  value="write"
327	                  checked={scopes.write}
328	                  onChange={(e) => setScopes((s) => ({ ...s, write: e.target.checked }))}
329	                />{" "}
330	                write
331	              </label>
332	            </div>
333	            <p className="mt-2 text-xs text-slate-500">
334	              The public API is read-only today — <code className="text-brand-200">GET /api/v1/servers</code> is
335	              the only endpoint. A <strong>write</strong> scope is accepted and stored for when
336	              mutating endpoints ship, but it grants nothing yet.
337	            </p>
338	          </div>
339	        </div>
340	        <button className="btn-primary" disabled={pending}>
341	          {pending ? "Creating…" : "Create token"}
342	        </button>
343	      </form>
344	    </div>
345	  );
346	}
