3	import { useEffect } from "react";
4	
5	/**
6	 * Invisible helper on the register page. If the visitor arrived via a referral
7	 * link (?ref=CODE), it stashes the code in a cookie so the `register` server
8	 * action can attribute the signup. Reads window.location directly to avoid a
9	 * Suspense boundary requirement.
10	 */
11	export function ReferralCapture() {
12	  useEffect(() => {
13	    try {
14	      const params = new URLSearchParams(window.location.search);
15	      const ref = params.get("ref");
16	      if (!ref) return;
17	      const code = ref.trim().toUpperCase().slice(0, 32);
18	      if (!/^[A-Z0-9_-]+$/.test(code)) return;
19	      // 30-day cookie, readable by the server action.
20	      document.cookie = `nxeon_ref=${encodeURIComponent(code)}; path=/; max-age=${60 * 60 * 24 * 30}; SameSite=Lax`;
21	    } catch {
22	      /* non-fatal */
23	    }
24	  }, []);
25	  return null;
26	}
