85	        <Link href="/dashboard" className="btn-ghost px-3 py-1 text-xs">
86	          Not now
87	        </Link>
88	        <span className="text-[11px] text-slate-500">
89	          There's nothing to decline — ignore the link and it expires on its own.
90	        </span>
91	      </div>
92	      {err && <p className="text-sm text-red-400">{err}</p>}
93	    </div>
94	  );
95	}
