3	import { useState } from "react";
4	import { dismissAnnouncement, type AnnouncementView } from "@/lib/actions-broadcast";
5	
6	const TONE: Record<string, string> = {
7	  INFO: "border-brand-500/30 bg-brand-500/[0.08] text-brand-100",
8	  SUCCESS: "border-emerald-500/30 bg-emerald-500/[0.08] text-emerald-100",
9	  WARNING: "border-amber-500/30 bg-amber-500/[0.08] text-amber-100",
10	  CRITICAL: "border-red-500/30 bg-red-500/[0.08] text-red-100",
11	};
