13	/** Dismissible admin broadcasts, shown at the top of the customer portal. Each
14	 *  dismissal is persisted per-user (server-side), so it stays gone across pages
15	 *  and devices. Optimistic: it disappears immediately, then records the dismissal. */
16	export function AnnouncementBanner({ announcements }: { announcements: AnnouncementView[] }) {
17	  const [hidden, setHidden] = useState<Set<string>>(new Set());
18	  const visible = announcements.filter((a) => !hidden.has(a.id));
19	  if (visible.length === 0) return null;
20	
21	  return (
22	    <div className="mb-4 space-y-2">
23	      {visible.map((a) => (
24	        <div key={a.id} className={`flex items-start justify-between gap-3 rounded-xl border px-4 py-3 text-sm ${TONE[a.level] ?? TONE.INFO}`}>
25	          <div className="min-w-0">
26	            <p className="font-semibold">{a.title}</p>
27	            {a.body && <p className="mt-0.5 whitespace-pre-wrap text-[13px] opacity-90">{a.body}</p>}
28	          </div>
29	          <button
30	            aria-label="Dismiss"
31	            className="shrink-0 rounded p-1 opacity-70 transition-opacity hover:opacity-100"
32	            onClick={() => {
33	              setHidden((prev) => new Set(prev).add(a.id));
34	              void dismissAnnouncement(a.id);
35	            }}
36	          >
37	            ✕
38	          </button>
39	        </div>
40	      ))}
41	    </div>
42	  );
43	}
